function restoreCore(core){clearObjects();records=structuredClone(core.objects);cameraState=structuredClone(core.camera);records.forEach(mount);select(records.some(o=>o.id===selected)?selected:records[0]?.id||null);syncCameraFields();resize();mark();}
function coreSnapshot(){return JSON.stringify({objects:records,camera:cameraState});}
function historyButtons(){$('undo').disabled=history.length<2;$('redo').disabled=!future.length;}
