$('undo').addEventListener('click',()=>{if(history.length<2)return;future.push(history.pop());restoreCore(JSON.parse(history.at(-1)));historyButtons();});
$('redo').addEventListener('click',()=>{if(!future.length)return;const current=future.pop();history.push(current);restoreCore(JSON.parse(current));historyButtons();});
const symbols={tuantuan:'◉',jiujiu:'◉',table:'▤',chair:'▥',sofa:'▤',box:'◇',ball:'○',cup:'∪',bowl:'∪',cabinet:'▥',screen:'▣',wall:'▥',doorway:'Π',platform:'▱'};
function refreshObjectList(){const list=$('object-list');list.replaceChildren();for(const item of records){const row=document.createElement('div');row.className='object-row'+(item.id===selected?' selected':'');const button=document.createElement('button');button.className='pick';button.setAttribute('aria-pressed',String(item.id===selected));const icon=document.createElement('span');icon.className='object-symbol';icon.textContent=symbols[item.kind]||'▥';const name=document.createElement('span');name.textContent=item.name;button.append(icon,name);button.addEventListener('click',()=>select(item.id));const visibility=document.createElement('button');visibility.className='visibility';visibility.textContent=item.visible?'●':'○';visibility.setAttribute('aria-label',(item.visible?'隐藏':'显示')+item.name);visibility.addEventListener('click',()=>{item.visible=!item.visible;updateRoot(item);if(selected===item.id)select(selected);else refreshObjectList();commit();});row.append(button,visibility);list.append(row);}$('object-count').textContent=records.length+' 个';syncHomeControls();}
