$('add-object').addEventListener('click',()=>{if(records.length>=80){toast('当前工程最多放置 80 个对象。');return;}const item=newObject($('add-kind').value);item.position=[0,0,.8];if(isCat(item.kind)&&records.some(o=>o.kind==='home-floor')){item.scale=[.38,.38,.38];item.position[1]=.025;}records.push(item);mount(item);select(item.id);commit();});
