function syncShotCamera(){const position=new THREE.Vector3(...cameraState.position),target=new THREE.Vector3(...cameraState.target);if(position.distanceTo(target)<.05){cameraState.target[2]-=.1;target.set(...cameraState.target);}shotCamera.position.copy(position);shotCamera.up.set(0,1,0);shotCamera.aspect=aspectValue(cameraState.aspect);shotCamera.setFocalLength(cameraState.focal);shotCamera.lookAt(target);shotCamera.rotateZ(rad(cameraState.roll));shotCamera.updateMatrixWorld(true);cameraProxy.position.copy(position);cameraProxy.quaternion.copy(shotCamera.quaternion);targetProxy.position.copy(target);helperCamera.copy(shotCamera);helperCamera.far=2.0;helperCamera.updateProjectionMatrix();helperCamera.updateMatrixWorld(true);frustum.update();$('lens-readout').textContent=cameraState.focal.toFixed(0)+' MM';}
function syncCameraFields(){['x','y','z'].forEach((axis,i)=>{$('cam-'+axis).value=Number(cameraState.position[i].toFixed(3));$('aim-'+axis).value=Number(cameraState.target[i].toFixed(3));});$('focal').value=cameraState.focal;$('focal-out').textContent=cameraState.focal.toFixed(0)+' mm';$('roll').value=cameraState.roll;$('roll-out').textContent=cameraState.roll.toFixed(0)+'°';$('aspect').value=cameraState.aspect;syncHomeControls();dirty=true;}
['cam','aim'].forEach(prefix=>['x','y','z'].forEach((axis,i)=>$(prefix+'-'+axis).addEventListener('change',e=>{const input=e.target,value=Number(input.value);if(!Number.isFinite(value))return;cameraState[prefix==='cam'?'position':'target'][i]=Math.max(+input.min,Math.min(+input.max,value));syncCameraFields();commit();})));
['focal','roll'].forEach(id=>{$(id).addEventListener('input',()=>{cameraState[id]=+$(id).value;syncCameraFields();mark();});$(id).addEventListener('change',commit);});
document.querySelectorAll('[data-lens]').forEach(b=>b.addEventListener('click',()=>{cameraState.focal=+b.dataset.lens;syncCameraFields();commit();}));
$('aspect').addEventListener('change',()=>{cameraState.aspect=$('aspect').value;syncCameraFields();resize();commit();});
function selectedCenter(){const root=roots.get(selected);if(root){return new THREE.Box3().setFromObject(root).getCenter(new THREE.Vector3());}if(selected==='@camera')return cameraProxy.position.clone();if(selected==='@target')return targetProxy.position.clone();return new THREE.Vector3(0,.7,0);}
$('aim-selected').addEventListener('click',()=>{if(!roots.has(selected)){toast('先选择需要对准的角色或物品。');return;}cameraState.target=selectedCenter().toArray();syncCameraFields();commit();toast('摄影机已对准 '+records.find(o=>o.id===selected).name);});
$('focus-selected').addEventListener('click',()=>{const center=selectedCenter(),offset=editorCamera.position.clone().sub(orbit.target).normalize();const root=roots.get(selected),size=root?new THREE.Box3().setFromObject(root).getSize(new THREE.Vector3()).length():2;orbit.target.copy(center);editorCamera.position.copy(center).add(offset.multiplyScalar(Math.max(1.5,size*2.3)));orbit.update();dirty=true;});
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{const center=orbit.target.clone(),distance=Math.max(5,editorCamera.position.distanceTo(center));const offsets={perspective:[.6,.5,.8],top:[0,1,.001],front:[0,.05,1],side:[1,.05,0]};editorCamera.position.copy(center).add(new THREE.Vector3(...offsets[b.dataset.view]).normalize().multiplyScalar(distance));orbit.update();document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));dirty=true;}));
$('match-view').addEventListener('click',()=>{cameraState.position=editorCamera.position.toArray();cameraState.target=orbit.target.toArray();cameraState.focal=Math.max(18,Math.min(120,editorCamera.getFocalLength()));cameraState.roll=0;syncCameraFields();commit();toast('已采用当前视角；右侧显示所选画幅的实际取景');});
const raycaster=new THREE.Raycaster();raycaster.layers.enable(1);let pointerStart=null,wasTransforming=false;
transform.addEventListener('mouseDown',()=>{wasTransforming=true;});
$('editor-canvas').addEventListener('pointerdown',e=>{if(e.button!==0)return;pointerStart={x:e.clientX,y:e.clientY};wasTransforming=!!transform.dragging;});
$('editor-canvas').addEventListener('pointerup',e=>{if(!pointerStart||e.button!==0)return;const moved=Math.hypot(e.clientX-pointerStart.x,e.clientY-pointerStart.y);pointerStart=null;if(moved>5||wasTransforming||transform.dragging)return;const b=$('editor-canvas').getBoundingClientRect();raycaster.setFromCamera(new THREE.Vector2((e.clientX-b.left)/b.width*2-1,-(e.clientY-b.top)/b.height*2+1),editorCamera);if(poseEditor?.pick(raycaster)){dirty=true;return;}const candidates=records.filter(o=>o.visible).map(o=>roots.get(o.id));if($('show-camera').checked)candidates.push(cameraProxy,targetProxy);const hits=raycaster.intersectObjects(candidates,true);if(!hits.length){select(null);return;}let object=hits[0].object;while(object){if(object===cameraProxy){select('@camera');return;}if(object===targetProxy){select('@target');return;}if(object.userData.objectId){select(object.userData.objectId);return;}object=object.parent;}});
$('editor-canvas').addEventListener('contextmenu',e=>e.preventDefault());
$('show-grid').addEventListener('change',()=>{grid.visible=$('show-grid').checked;dirty=true;});$('show-labels').addEventListener('change',()=>{dirty=true;});$('show-camera').addEventListener('change',()=>{const visible=$('show-camera').checked;cameraProxy.visible=targetProxy.visible=frustum.visible=visible;if(!visible&&(selected==='@camera'||selected==='@target'))select(null);dirty=true;});$('show-thirds').addEventListener('change',()=>{$('thirds').hidden=!$('show-thirds').checked;});

function resize(){const stage=$('editor-stage'),shot=$('shot-stage');const w=Math.max(120,stage.clientWidth),h=Math.max(120,stage.clientHeight);editorRenderer.setSize(w,h,false);editorCamera.aspect=w/h;editorCamera.updateProjectionMatrix();const a=aspectValue(cameraState.aspect),sw=Math.max(100,shot.clientWidth-20),sh=Math.max(100,shot.clientHeight-20),fw=Math.min(sw,sh*a),fh=fw/a;$('shot-frame').style.width=fw+'px';$('shot-frame').style.height=fh+'px';shotRenderer.setSize(fw,fh,false);dirty=true;}
function updateLabels(){const container=$('editor-labels');container.replaceChildren();if(!$('show-labels').checked)return;for(const item of records){if(!item.visible)continue;const box=new THREE.Box3().setFromObject(roots.get(item.id)),center=box.getCenter(new THREE.Vector3());center.y=box.max.y+.10;const p=center.project(editorCamera);if(Math.abs(p.x)>1||Math.abs(p.y)>1||p.z>1||p.z< -1)continue;const label=document.createElement('span');label.className='object-label'+(item.id===selected?' selected':'');label.style.left=(p.x+1)*50+'%';label.style.top=(1-p.y)*50+'%';label.textContent=item.name;container.append(label);}}
function render(){poseEditor?.refreshHelpers();syncShotCamera();if(roots.has(selected)&&roots.get(selected).visible){selectionBox.setFromObject(roots.get(selected));selectionBox.visible=true;}else selectionBox.visible=false;scene.updateMatrixWorld(true);editorRenderer.render(scene,editorCamera);shotRenderer.render(scene,shotCamera);updateLabels();}

function refreshReferences(){const container=$('references');container.replaceChildren();references.forEach(ref=>{const b=document.createElement('button');b.className='ref-card';const img=document.createElement('img');img.src=ref.src;img.alt=ref.name;img.loading='lazy';const title=document.createElement('span');title.className='ref-label';title.textContent=ref.name;const role=document.createElement('span');role.className='ref-role';role.textContent=roleNames[ref.role];b.append(img,title,role);b.addEventListener('click',()=>{refEditing=ref.id;$('ref-title').textContent=ref.name;$('ref-full').src=ref.src;$('ref-name').value=ref.name;$('ref-role').value=ref.role;$('ref-dialog').showModal();});container.append(b);});}
$('close-reference').addEventListener('click',()=>$('ref-dialog').close());$('ref-dialog').addEventListener('click',e=>{if(e.target===$('ref-dialog')){const b=$('ref-dialog').getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)$('ref-dialog').close();}});
$('save-reference').addEventListener('click',()=>{const ref=references.find(r=>r.id===refEditing);if(ref){ref.name=$('ref-name').value.trim()||'参考图';ref.role=$('ref-role').value;mark();refreshReferences();}$('ref-dialog').close();});
$('delete-reference').addEventListener('click',()=>{references=references.filter(r=>r.id!==refEditing);refreshReferences();mark();$('ref-dialog').close();});
$('add-reference').addEventListener('click',()=>$('ref-file').click());
async function readFile(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('文件无法读取，请重试。'));reader.readAsDataURL(file);});}
async function checkImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('参考图片无法读取，请选择 JPG、PNG 或 WebP。'));img.src=src;});}
$('ref-file').addEventListener('change',async e=>{const files=[...e.target.files];let added=0;try{for(const file of files){if(references.length>=16)throw Error('最多可保留 16 张参考图。');if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('请选择 JPG、PNG 或 WebP；HEIC 请先转为 JPG。');if(file.size>15*1024*1024)throw Error('单张参考图片请控制在 15 MB 内。');const src=await readFile(file);await checkImage(src);references.push({id:crypto.randomUUID(),name:file.name.replace(/\.[^.]+$/,''),role:'prop',src});added++;}if(added){refreshReferences();mark();toast('已添加 '+added+' 张参考图，点击缩略图可设置用途');}}catch(err){if(added){refreshReferences();mark();}toast(err.message);}finally{e.target.value='';}});
const cachedData=new Map();
async function referenceData(ref){if(ref.src.startsWith('data:image/'))return ref.src;if(cachedData.has(ref.src))return cachedData.get(ref.src);if(!DEFAULT_REFERENCES.some(x=>x.src===ref.src))throw Error('参考图来源无效。');const response=await fetch(ref.src);if(!response.ok)throw Error('无法读取 '+ref.name+'，请稍后重试。');const data=await readFile(await response.blob());cachedData.set(ref.src,data);return data;}
function download(blob,name){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function task(fn){if(busy)return;busy=true;['export-frame','export-packet','save-project','open-project'].forEach(id=>$(id).disabled=true);try{await fn();}catch(err){toast(err.message||'操作未完成，请重试。');}finally{busy=false;['export-frame','export-packet','save-project','open-project'].forEach(id=>$(id).disabled=false);}}
function screenshot(){syncShotCamera();const old=shotRenderer.getSize(new THREE.Vector2()),pixelRatio=shotRenderer.getPixelRatio(),a=aspectValue(cameraState.aspect),w=a>=1?1920:Math.round(1920*a),h=a>=1?Math.round(1920/a):1920;const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;try{shotRenderer.setPixelRatio(1);shotRenderer.setSize(w,h,false);shotRenderer.render(scene,shotCamera);canvas.getContext('2d').drawImage(shotRenderer.domElement,0,0);}finally{shotRenderer.setPixelRatio(pixelRatio);shotRenderer.setSize(old.x,old.y,false);dirty=true;}return canvas;}
function png(canvas){return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('截图导出失败，请重试。')),'image/png'));}
function annotated(canvas){
  const out=document.createElement('canvas');out.width=canvas.width;out.height=canvas.height;const ctx=out.getContext('2d');ctx.drawImage(canvas,0,0);
  const font=Math.max(19,Math.round(out.width/52)),placed=[];ctx.font='500 '+font+'px sans-serif';ctx.textBaseline='middle';let index=1;
  for(const item of records){
    if(!item.visible)continue;const center=new THREE.Box3().setFromObject(roots.get(item.id)).getCenter(new THREE.Vector3()),p=center.project(shotCamera);
    if(Math.abs(p.x)>.98||Math.abs(p.y)>.98||Math.abs(p.z)>1)continue;
    const name=String(index++)+'. '+item.name.slice(0,18),width=ctx.measureText(name).width+20,height=font*1.6,px=(p.x+1)*out.width/2,py=(1-p.y)*out.height/2;
    const x=Math.max(8,Math.min(out.width-width-8,px-width/2));let y=Math.max(height,Math.min(out.height-height,py-height));
    for(const offset of [-1,-2.3,1,2.3,-3.6,3.6,-4.9,4.9]){const candidate=Math.max(height,Math.min(out.height-height,py+height*offset));if(!placed.some(b=>x<b.x+b.w+8&&x+width+8>b.x&&candidate-height/2<b.y+b.h/2+6&&candidate+height/2+6>b.y-b.h/2)){y=candidate;break;}}
    placed.push({x,y,w:width,h:height});ctx.strokeStyle='rgba(32,48,60,.85)';ctx.lineWidth=Math.max(2,out.width/800);ctx.beginPath();ctx.moveTo(px,py);ctx.lineTo(x+width/2,y);ctx.stroke();ctx.fillStyle='rgba(22,32,44,.92)';ctx.fillRect(x,y-height/2,width,height);ctx.fillStyle='#f3f7fa';ctx.fillText(name,x+10,y);
  }
  return out;
}
function makeBrief(){syncShotCamera();const lines=['根据白模构图图生成一张正式镜头参考图。','01-white-model.png 是空间和构图基准；02-labeled-layout.png 只用于识别对象。保持白模中的摄影机视角、透视、画面比例、角色姿态、相对大小、前后关系与遮挡。','画幅 '+cameraState.aspect+'；全画幅等效焦距约 '+cameraState.focal.toFixed(0)+' mm；摄影机位置 '+cameraState.position.map(x=>x.toFixed(2)).join(', ')+'；注视点 '+cameraState.target.map(x=>x.toFixed(2)).join(', ')+'；画面倾斜 '+cameraState.roll.toFixed(0)+'°。','','场景对象（可见性与遮挡以白模图为准）：'];for(const item of records){if(!item.visible)continue;const center=new THREE.Box3().setFromObject(roots.get(item.id)).getCenter(new THREE.Vector3()),p=center.clone().project(shotCamera),depth=center.clone().applyMatrix4(shotCamera.matrixWorldInverse).z;const where=Math.abs(p.x)>1||Math.abs(p.y)>1||depth>0?'中心在画面外':p.x<-.22?'画面左侧':p.x>.22?'画面右侧':'画面中部';lines.push('- '+item.name+'（'+TYPES[item.kind]+'）：'+where+'，距摄影机约 '+center.distanceTo(shotCamera.position).toFixed(1)+' m'+(isCat(item.kind)?'，基础姿势：'+POSES[item.pose.preset]+'（最终关节姿势以白模截图为准）':'')+'。');}lines.push('','外观参考：');references.forEach((ref,i)=>lines.push('- '+String(i+1).padStart(2,'0')+'-'+safeName(ref.name)+'：'+roleNames[ref.role]+'。'));lines.push('','团团、久久的脸型、眼睛、耳朵与毛色按各自角色参考；环境与核心物品按对应参考补充材质和细节。参考图决定外观，白模图决定空间与姿势。将白模替换成自然的角色和物体，保留原有构图，不加入标记文字、坐标轴、网格或模型底座。','在没有对应外观参考时，按对象名称补充合理外观；不要为了套用参考图片原有构图而移动角色或物品。');return lines.join('\n');}
function safeName(name){return String(name).replace(/[\\/:*?"<>|\u0000-\u001f]/g,'-').slice(0,70)||'reference';}
$('refresh-prompt').addEventListener('click',()=>{$('prompt').value=makeBrief();promptEdited=false;toast('已按当前白模与机位更新说明');});$('prompt').addEventListener('input',()=>{promptEdited=true;mark();});
$('copy-prompt').addEventListener('click',async()=>{if(!promptEdited)$('prompt').value=makeBrief();try{await navigator.clipboard.writeText($('prompt').value);toast('镜头说明已复制');}catch{$('prompt').focus();$('prompt').select();toast('请复制已选中的镜头说明');}});
$('export-frame').addEventListener('click',()=>task(async()=>{download(await png(screenshot()),'镜场-白模构图.png');toast('已导出干净的白模截图，不包含坐标轴和辅助线');}));
$('export-packet').addEventListener('click',()=>task(async()=>{if(!window.JSZip)throw Error('素材包组件尚未加载，请稍后重试。');toast('正在整理白模截图、标记图和参考素材…');const canvas=screenshot(),labeled=annotated(canvas),brief=promptEdited?$('prompt').value:makeBrief(),refsSnapshot=references.map(r=>({...r})),zip=new window.JSZip();zip.file('01-white-model.png',await png(canvas));zip.file('02-labeled-layout.png',await png(labeled));zip.file('03-shot-brief.txt',brief);for(let i=0;i<refsSnapshot.length;i++){const ref=refsSnapshot[i],data=await referenceData(ref),extension=data.startsWith('data:image/jpeg')?'jpg':data.startsWith('data:image/webp')?'webp':'png';zip.file('references/'+String(i+1).padStart(2,'0')+'-'+safeName(ref.name)+'.'+extension,data.split(',')[1],{base64:true});}zip.file('使用说明.txt','先将 01-white-model.png 作为构图参考，再提供对应角色、环境和核心物品的参考图。02-labeled-layout.png 用于核对角色位置；标签不应保留在最终画面中。03-shot-brief.txt 可编辑后交给图像生成模型。\n这些是真实三维白模的截图，但不是角色最终材质或动画。生成结果仍需检查构图和角色一致性。\n若要继续调整白模，请在网页中单独使用“保存工程”。');const blob=await zip.generateAsync({type:'blob',compression:'DEFLATE',compressionOptions:{level:4}});download(blob,'镜场-镜头参考素材包.zip');toast('素材包已导出：白模、对象标记、镜头说明和全部参考图');}));
$('save-project').addEventListener('click',()=>task(async()=>{const savedRevision=revision,refsSnapshot=references.map(r=>({...r})),project={format:'shotroom-blocking',version:4,objects:structuredClone(records),camera:structuredClone(cameraState),references:[],editor:{position:editorCamera.position.toArray(),target:orbit.target.toArray()},brief:promptEdited?$('prompt').value:''};for(const ref of refsSnapshot)project.references.push({...ref,src:await referenceData(ref)});download(new Blob([JSON.stringify(project)],{type:'application/json'}),'镜场-三维镜头工程.json');if(revision===savedRevision)modified=false;toast('三维工程已保存，包含姿势、机位和参考图');}));
$('open-project').addEventListener('click',()=>$('project-file').click());
$('project-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;await task(async()=>{if(file.size>140*1024*1024)throw Error('工程文件请控制在 140 MB 内。');let raw;try{raw=JSON.parse(await file.text());}catch{throw Error('工程文件不是有效的 JSON。');}const project=validateProject(raw);for(const ref of project.references)await checkImage(ref.src);if(modified&&!confirm('打开工程会替换当前场景与参考素材。请确认已保存需要保留的内容。'))return;restoreCore(project);references=project.references;refreshReferences();editorCamera.position.set(...project.editor.position);orbit.target.set(...project.editor.target);orbit.update();promptEdited=!!project.brief;$('prompt').value=project.brief||makeBrief();history.length=0;future.length=0;history.push(coreSnapshot());historyButtons();modified=false;toast(project.migrated?'旧版照片工程已转为白模起始场景，原图片保留为外观参考':'工程已恢复：白模、姿势、机位与参考图');});e.target.value='';});
window.addEventListener('beforeunload',e=>{if(modified){e.preventDefault();e.returnValue='';}});
window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||$('ref-dialog').open)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$(e.shiftKey?'redo':'undo').click();return;}const key=e.key.toLowerCase();if(['w','e','r'].includes(key)){setTool({w:'translate',e:'rotate',r:'scale'}[key]);}else if(key==='f'){$('focus-selected').click();}else if(key==='delete'||key==='backspace'){e.preventDefault();$('remove-object').click();}else if(key==='escape')select(null);});
for(const renderer of [editorRenderer,shotRenderer])renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();toast('三维画面暂时中断，请保存工程后重新打开网页。');});
new ResizeObserver(resize).observe($('editor-stage'));new ResizeObserver(resize).observe($('shot-stage'));
poseEditor=createPoseEditor({scene,transform,roots,getItem:()=>records.find(o=>o.id===selected),updateRoot,syncInspector,mark,commit,toast,editorOnly,setTool});
records.forEach(mount);select(records.find(o=>o.kind==='tuantuan')?.id||records[0].id);syncCameraFields();refreshReferences();orbit.update();resize();render();$('prompt').value=makeBrief();history.push(coreSnapshot());historyButtons();modified=false;dirty=false;
function loop(){requestAnimationFrame(loop);if(dirty&&!transform.dragging){render();dirty=false;}else if(transform.dragging){render();dirty=false;}}
requestAnimationFrame(loop);
